import {
    createClient,
    Client,
    Transport,
} from "@connectrpc/connect"

import {
    createGrpcWebTransport,
} from "@connectrpc/connect-web"

import { ActivityService } from "../../gen/avn/connect/v1/activities_connect.js"
import { AvnfsService } from "../../gen/avn/connect/v1/avnfs_connect.js"
import { BlockadeService } from "../../gen/avn/connect/v1/blockade_connect.js"
import { CategoryService } from "../../gen/avn/connect/v1/categories_connect.js"
import { CertificateService } from "../../gen/avn/connect/v1/certificates_connect.js"
import { ChannelService } from "../../gen/avn/connect/v1/channels_connect.js"
import { ClientService } from "../../gen/avn/connect/v1/clients_connect.js"
import { CloudService } from "../../gen/avn/connect/v1/cloud_connect.js"
import { ContentService } from "../../gen/avn/connect/v1/content_connect.js"
import { CountryService } from "../../gen/avn/connect/v1/countries_connect.js"
import { DimensionService } from "../../gen/avn/connect/v1/dimensions_connect.js"
import { GeoService } from "../../gen/avn/connect/v1/geo_connect.js"
import { Health } from "../../gen/grpc/health/v1/healthcheck_connect.js"
import { KtxService } from "../../gen/avn/connect/v1/ktx_connect.js"
import { LanguageService } from "../../gen/avn/connect/v1/languages_connect.js"
import { LicenseService } from "../../gen/avn/connect/v1/licenses_connect.js"
import { MediaService } from "../../gen/avn/connect/v1/media_connect.js"
import { NeighborService } from "../../gen/avn/connect/v1/neighbors_connect.js"
import { OrganizationService } from "../../gen/avn/connect/v1/organizations_connect.js"
import { PassService } from "../../gen/avn/connect/v1/passes_connect.js"
import { PermissionService } from "../../gen/avn/connect/v1/permissions_connect.js"
import { ProfileService } from "../../gen/avn/connect/v1/profiles_connect.js"
import { RoleService } from "../../gen/avn/connect/v1/roles_connect.js"
import { RoomService } from "../../gen/avn/connect/v1/rooms_connect.js"
import { SpeechService } from "../../gen/avn/connect/v1/speech_connect.js"
import { TagService } from "../../gen/avn/connect/v1/tags_connect.js"
import { ThreeSixtyCitiesService } from "../../gen/avn/connect/v1/three_sixty_cities_connect.js"
import { TranscriptionService } from "../../gen/avn/connect/v1/transcriptions_connect.js"
import { TranslationService } from "../../gen/avn/connect/v1/translations_connect.js"
import { UserService } from "../../gen/avn/connect/v1/users_connect.js"

export const GwebUrl = "https://gweb.avncloud.com"
export const GwebAlphaUrl = "https://gweb-alpha.avncloud.com"

export class ConnectServices {

    // Expects a grpc-web endpoint for the AVN Connect services
    constructor(public readonly gwebUrl: string = GwebUrl) {
        console.info(`ConnectServices endpoint '${gwebUrl}'`)

        this.transport = createGrpcWebTransport({ baseUrl: this.gwebUrl })

        this.Activities = createClient(ActivityService, this.transport)
        this.Avnfs = createClient(AvnfsService, this.transport)
        this.Blockade = createClient(BlockadeService, this.transport)
        this.Categories = createClient(CategoryService, this.transport)
        this.Certificates = createClient(CertificateService, this.transport)
        this.Channels = createClient(ChannelService, this.transport)
        this.Clients = createClient(ClientService, this.transport)
        this.Cloud = createClient(CloudService, this.transport)
        this.Content = createClient(ContentService, this.transport)
        this.Countries = createClient(CountryService, this.transport)
        this.Dimensions = createClient(DimensionService, this.transport)
        this.Geo = createClient(GeoService, this.transport)
        this.Health = createClient(Health, this.transport)
        this.Ktx = createClient(KtxService, this.transport)
        this.Languages = createClient(LanguageService, this.transport)
        this.Licenses = createClient(LicenseService, this.transport)
        this.Media = createClient(MediaService, this.transport)
        this.Neighbors = createClient(NeighborService, this.transport)
        this.Organizations = createClient(OrganizationService, this.transport)
        this.Passes = createClient(PassService, this.transport)
        this.Permissions = createClient(PermissionService, this.transport)
        this.Profiles = createClient(ProfileService, this.transport)
        this.Roles = createClient(RoleService, this.transport)
        this.Rooms = createClient(RoomService, this.transport)
        this.Speech = createClient(SpeechService, this.transport)
        this.Tags = createClient(TagService, this.transport)
        this.ThreeSixtyCities = createClient(ThreeSixtyCitiesService, this.transport)
        this.Transcriptions = createClient(TranscriptionService, this.transport)
        this.Translations = createClient(TranslationService, this.transport)
        this.Users = createClient(UserService, this.transport)
    }

    private transport: Transport

    // Services

    public Activities : Client<typeof ActivityService>
    public Avnfs : Client<typeof AvnfsService>    
    public Blockade : Client<typeof BlockadeService>    
    public Categories : Client<typeof CategoryService>
    public Certificates : Client<typeof CertificateService>    
    public Channels : Client<typeof ChannelService>
    public Clients : Client<typeof ClientService>    
    public Cloud : Client<typeof CloudService>    
    public Content : Client<typeof ContentService>    
    public Countries : Client<typeof CountryService>    
    public Dimensions : Client<typeof DimensionService>
    public Geo : Client<typeof GeoService>    
    public Health : Client<typeof Health>
    public Ktx : Client<typeof KtxService>
    public Languages : Client<typeof LanguageService>    
    public Licenses : Client<typeof LicenseService>    
    public Media : Client<typeof MediaService>    
    public Neighbors : Client<typeof NeighborService>    
    public Organizations : Client<typeof OrganizationService>    
    public Passes : Client<typeof PassService>    
    public Permissions : Client<typeof PermissionService>    
    public Profiles : Client<typeof ProfileService>
    public Roles : Client<typeof RoleService>    
    public Rooms : Client<typeof RoomService>    
    public Speech : Client<typeof SpeechService>    
    public Tags : Client<typeof TagService>    
    public ThreeSixtyCities : Client<typeof ThreeSixtyCitiesService>    
    public Transcriptions : Client<typeof TranscriptionService>    
    public Translations : Client<typeof TranslationService>    
    public Users : Client<typeof UserService>    

}


